#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

typedef struct {
    char* s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok* t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' ||
            t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
        int token_len = t->pos - start;
        char* token = (char*)malloc(token_len + 1);
        if (!token) return NULL;
        strncpy(token, t->s + start, token_len);
        token[token_len] = '\0';
        return token;
    } else if (t->s[t->pos] == '"') {
        t->pos++;
        while (t->pos < t->len && t->s[t->pos] != '"') t->pos++;
        if (t->pos < t->len) t->pos++;
        int token_len = t->pos - start;
        char* token = (char*)malloc(token_len + 1);
        if (!token) return NULL;
        strncpy(token, t->s + start, token_len);
        token[token_len] = '\0';
        return token;
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' &&
               t->s[t->pos] != ']' && t->s[t->pos] != '[') t->pos++;
        int token_len = t->pos - start;
        char* token = (char*)malloc(token_len + 1);
        if (!token) return NULL;
        strncpy(token, t->s + start, token_len);
        token[token_len] = '\0';
        int idx = token_len - 1;
        while (idx >= 0 &&
               (token[idx] == ' ' || token[idx] == '\t' ||
                token[idx] == '\r' || token[idx] == '\n')) {
            token[idx] = '\0';
            idx--;
        }
        return token;
    }
}

static char* parse_string(Tok* t) {
    char* tok = nextToken(t);
    if (!tok) return NULL;
    if (tok[0] == '"') {
        int len = (int)strlen(tok);
        if (len >= 2 && tok[len - 1] == '"') tok[len - 1] = '\0';
        char* res = (char*)malloc(strlen(tok));
        if (!res) { free(tok); return NULL; }
        strcpy(res, tok + 1);
        free(tok);
        return res;
    }
    return tok;
}

bool detectCapitalUse(char* word) {
    int upper = 0;
    int len = (int)strlen(word);
    for (int i = 0; i < len; i++) {
        if (isupper((unsigned char)word[i])) upper++;
    }
    return upper == 0 || upper == len ||
           (upper == 1 && isupper((unsigned char)word[0]));
}

